Rules.InvariantScript:
If(!varCargado,
    Concurrent(
        ClearCollect(colPersonal, tblPersonal),
        If(IsError(ClearCollect(colIngresos, tblIngresos)), false),
        ClearCollect(colHistorial, tblHistorial),
        ClearCollect(colDonantes, tblDonantes)
    );
    Set(varYo, LookUp(colPersonal, Lower(Trim(Correo)) = Lower(User().Email) && Activo = "Sí"));
    Set(varArea, If(IsBlank(varYo), "Sin acceso", varYo.Area));
    Set(varCargado, true)
);
If(IsBlank(varTema), Set(varTema, "claro"));
If(IsBlank(varCodigosMarb), Set(varCodigosMarb, ""));
If(IsBlank(varMarbLink), Set(varMarbLink, ""); Set(varMarbBuscando, false); Set(varMarbExcel, false); ClearCollect(colMarbetes, FirstN(Table({codigo: "", dewey: "", cutter: "", anio: "", copia: "", unidad: "", biblioteca: ""}), 0)); ClearCollect(colMarbNo, FirstN(Table({Value: ""}), 0)); Set(varMarbSel, First(colMarbetes)));
SetFocus(txtBuscarMb)

With({cods: Distinct(Filter(ForAll(Split(Substitute(Substitute(Substitute(txtCodigosMb.Text, Char(13), ""), ",", Char(10)), ";", Char(10)), Char(10)), {c: Trim(Value)}), !IsBlank(c)), c)},
    If(CountRows(cods) = 0, Notify("Agregue al menos un código.", NotificationType.Warning),
        Set(varMarbBuscando, true);
        Set(varMarbRes, IfError('FolioMarbetes'.Run(Concat(cods, Value, "|")), Notify("No se pudo consultar FOLIO (flujo FolioMarbetes): " & FirstError.Message, NotificationType.Error); Blank()));
        Set(varMarbBuscando, false);
        If(IsBlank(varMarbRes), Notify("No se pudo consultar FOLIO. Revise el flujo FolioMarbetes.", NotificationType.Error),
            ClearCollect(colMarbetes, ForAll(Table(ParseJSON(Coalesce(varMarbRes.datos, "[]"))), {
                codigo: Text(ThisRecord.Value.codigo),
                dewey: Text(ThisRecord.Value.dewey),
                cutter: Text(ThisRecord.Value.cutter),
                anio: Text(ThisRecord.Value.anio),
                copia: Text(ThisRecord.Value.copia),
                unidad: Text(ThisRecord.Value.unidad),
                biblioteca: Text(ThisRecord.Value.biblioteca)
            }));
            Set(varMarbLink, "");
            Set(varMarbSel, First(colMarbetes));
            ClearCollect(colMarbNo, Filter(cods, !(Value in colMarbetes.codigo)));
            Notify(CountRows(colMarbetes) & " marbetes listos para revisar" & If(CountRows(colMarbNo) > 0, " · " & CountRows(colMarbNo) & " códigos no encontrados", ""), If(CountRows(colMarbNo) > 0, NotificationType.Warning, NotificationType.Success))
        )
    )
)

If(CountRows(colMarbetes) = 0, Notify("Primero revise los códigos.", NotificationType.Warning),
    Copy(With({nl: Char(13) & Char(10)}, Substitute(Substitute("^Q40,4" & nl & "^W100" & nl & "^H10" & nl & "^P1" & nl & "^S5" & nl & "^AD" & nl & "^C1" & nl & "^R8" & nl & "~Q-12" & nl & "^O0" & nl & "^D0" & nl & "^E12" & nl & "~R200" & nl & "^XSET,ROTATION,0" & nl & Concat(colMarbetes, "^L" & nl & "AE,255,154,1,1,0,1," & Trim(unidad) & nl & "AE,292,155,1,1,0,1," & Trim(biblioteca) & nl & "BA3,38,20,2,6,120,0,0," & Trim(codigo) & nl & "AF,38,148,1,1,0,0," & Trim(codigo) & nl & "AF,499,11,1,1,0,0," & Trim(dewey) & nl & "AF,499,61,1,1,0,0," & Trim(cutter) & nl & "AF,499,111,1,1,0,0," & Trim(anio) & nl & "AF,499,158,1,1,0,0," & Trim(copia) & nl & "E", nl) & nl, "Ñ", Char(165)), "ñ", Char(164))));
    Notify(CountRows(colMarbetes) & " etiquetas copiadas. En GoLabel: clic en el Área de comandos, Ctrl+V y Enviar." & If(CountRows(Filter(colMarbetes, (IsBlank(Trim(ThisRecord.dewey)) || IsBlank(Trim(ThisRecord.cutter)) || !IsMatch(Trim(ThisRecord.unidad), "^[A-ZÑ][A-ZÑ-]{1,9}$")))) > 0, " Ojo: " & CountRows(Filter(colMarbetes, (IsBlank(Trim(ThisRecord.dewey)) || IsBlank(Trim(ThisRecord.cutter)) || !IsMatch(Trim(ThisRecord.unidad), "^[A-ZÑ][A-ZÑ-]{1,9}$")))) & " por revisar.", ""), NotificationType.Success))

ControlPropertyState.AutoRuleBindingString:
If(CountRows(colMarbetes) = 0, Notify("Primero revise los códigos.", NotificationType.Warning),
    Copy(With({nl: Char(13) & Char(10)}, "^Q40,4" & nl & "^W100" & nl & "^H10" & nl & "^P1" & nl & "^S5" & nl & "^AD" & nl & "^C1" & nl & "^R8" & nl & "~Q-12" & nl & "^O0" & nl & "^D0" & nl & "^E12" & nl & "~R200" & nl & "^XSET,ROTATION,0" & nl & Concat(colMarbetes, "^L" & nl & "AE,255,154,1,1,0,1," & Trim(unidad) & nl & "AE,292,155,1,1,0,1," & Trim(biblioteca) & nl & "BA3,38,20,2,6,120,0,0," & Trim(codigo) & nl & "AF,38,148,1,1,0,0," & Trim(codigo) & nl & "AF,499,11,1,1,0,0," & Trim(dewey) & nl & "AF,499,61,1,1,0,0," & Trim(cutter) & nl & "AF,499,111,1,1,0,0," & Trim(anio) & nl & "AF,499,158,1,1,0,0," & Trim(copia) & nl & "E", nl) & nl));
    Notify(CountRows(colMarbetes) & " etiquetas copiadas. En GoLabel: clic en el Área de comandos, Ctrl+V y Enviar." & If(CountRows(Filter(colMarbetes, (IsBlank(Trim(ThisRecord.dewey)) || IsBlank(Trim(ThisRecord.cutter)) || !IsMatch(Trim(ThisRecord.unidad), "^[A-ZÑ][A-ZÑ-]{1,9}$")))) > 0, " Ojo: " & CountRows(Filter(colMarbetes, (IsBlank(Trim(ThisRecord.dewey)) || IsBlank(Trim(ThisRecord.cutter)) || !IsMatch(Trim(ThisRecord.unidad), "^[A-ZÑ][A-ZÑ-]{1,9}$")))) & " por revisar.", ""), NotificationType.Success))

Rules.InvariantScript:
If(!IsBlank(varMarbLink),
    Download(varMarbLink & If("?" in varMarbLink, "&", "?") & "download=1"); Set(varMarbLink, ""),
    Set(varMarbExcel, true);
    Set(varMarbLink, IfError('FolioMarbetesExcel'.Run(JSON(ForAll(colMarbetes As m, {'Código de Barras': m.codigo, 'Clasificación Dewey': m.dewey, 'Clasificación Cutter': m.cutter, 'Año de Publicación': m.anio, 'Número Copia': m.copia, 'Unidad Académica': m.unidad, Biblioteca: m.biblioteca}), JSONFormat.Compact)).link, Notify("No se pudo crear el Excel (flujo FolioMarbetesExcel): " & FirstError.Message, NotificationType.Error); ""));
    Set(varMarbExcel, false);
    If(!IsBlank(varMarbLink), Notify("Excel creado con " & CountRows(colMarbetes) & " marbetes. Pulse ⤓ BAJAR EXCEL para descargarlo.", NotificationType.Success),
        Notify("El flujo FolioMarbetesExcel no devolvió el enlace del archivo. Revise su historial de ejecuciones en Power Automate.", NotificationType.Error)))
